export const transferredDirectCases={};

function addCross(number,keys,source,scenario,items){
 items.forEach(([question,key,...other],i)=>{
  other.splice(keys[i],0,key);
  transferredDirectCases[`CROSS-${number}-${i+1}`]={source,scenario,question,unsafeAnswer:i===4,
   choices:other.map(o=>o[0]),reasons:other.map(o=>o[1]),choiceSources:other.map(o=>o[2]??source)};
 });
}
transferredDirectCases['CROSS-004-5']={source:orthostatic,
 scenario:'An older adult becomes dizzy and unsteady on standing after bed rest. The patient has not been assessed for safe independent walking since the symptoms began.',
 question:'Which proposed response should the nurse challenge?',unsafeAnswer:true,
 choices:['Send the dizzy patient to walk to the bathroom alone','Support the patient in a safe seated or lying position','Assess symptoms and obtain appropriate physiological observations','Arrange assistance and reassess the mobility plan'],
 reasons:['Observed dizziness and instability make unsupported walking unsafe. Prevent a fall and assess the cause before another attempt.','A safe supported position addresses the immediate fall risk while the patient is assessed.','Positional symptoms warrant assessment, including blood pressure and pulse when safe, and review of possible contributors.','The assistance level should reflect the new symptoms and current function rather than an outdated mobility label.']};

